import math
import torch
import torch.nn as nn
import torch.nn.init as init
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor conv_hw_forward(torch::Tensor x,
                               torch::Tensor weight,
                               c10::optional<torch::Tensor> bias,
                               int stride, int padding, int dilation, int groups);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

// A cooperative tiled kernel that computes a 2D convolution (over the H,W
// spatial dims) with kernel (Kh, Kw), applied independently for every
// (batch, depth) slice, since the actual conv kernel has depth-extent 1.
// This corresponds to nn.Conv3d(..., kernel_size=(K,K,1), ...) with
// groups == 1.
template <typename T, int TILE_OH, int TILE_OW, int CIN, int KH, int KW>
__global__ void conv_hw_tiled_kernel_cached(
    const T* __restrict__ X,   // [N, Cin, H, W, D]
    const T* __restrict__ Wt,  // [Cout, Cin, Kh, Kw]
    const T* __restrict__ Bias,// [Cout] or nullptr
    T* __restrict__ Y,         // [N, Cout, Hout, Wout, Dout]
    int N, int H, int W, int D,
    int Cout,
    int Hout, int Wout, int Dout,
    int stride, int padding, int dilation,
    int patch_h, int patch_w)
{
  // CIN, KH, KW are compile-time template constants (specialized to the
  // actual layer shape at dispatch time). This lets the per-thread
  // register cache below be fully statically unrolled, so the compiler
  // can map every cached input value to a physical register instead of
  // spilling a dynamically-indexed array to slow local memory (which is
  // what happens when Cin/Kh/Kw are only known at runtime).
  extern __shared__ __align__(16) unsigned char smem_raw[];
  T* sW_ptr = reinterpret_cast<T*>(smem_raw);
  T* sX_ptr = sW_ptr + (size_t)Cout * CIN * KH * KW;
  auto sW = make_tensor(make_smem_ptr(sW_ptr),
                         make_shape(Cout, CIN, KH, KW),
                         make_stride(CIN * KH * KW, KH * KW, KW, 1));
  auto sX = make_tensor(make_smem_ptr(sX_ptr),
                         make_shape(patch_h, patch_w, CIN, D),
                         make_stride(patch_w * CIN * D, CIN * D, D, 1));
  const int tile_idx_w = blockIdx.x;
  const int tile_idx_h = blockIdx.y;
  const int n  = blockIdx.z;
  const int oh_base = tile_idx_h * TILE_OH;
  const int ow_base = tile_idx_w * TILE_OW;
  const int tid = threadIdx.y * blockDim.x + threadIdx.x;
  const int num_threads = blockDim.x * blockDim.y;
  const int wsize = Cout * CIN * KH * KW;
  {
    const int wsize4 = wsize / 4;
    const float4* Wt4 = reinterpret_cast<const float4*>(Wt);
    float4* sW4 = reinterpret_cast<float4*>(sW_ptr);
    for (int idx = tid; idx < wsize4; idx += num_threads) {
      sW4[idx] = Wt4[idx];
    }
    for (int idx = wsize4 * 4 + tid; idx < wsize; idx += num_threads) {
      sW_ptr[idx] = Wt[idx];
    }
  }
  const int64_t sXn = (int64_t)CIN * H * W * D;
  const int64_t sXc = (int64_t)H * W * D;
  const int64_t sXh = (int64_t)W * D;
  const int64_t sXw = (int64_t)D;
  const int in_h_base = oh_base * stride - padding;
  const int in_w_base = ow_base * stride - padding;
  const int oh = oh_base + threadIdx.y;
  const int ow = ow_base + threadIdx.x;
  const bool valid_out = (oh < Hout) && (ow < Wout);
  const int64_t sYn = (int64_t)Cout * Hout * Wout * Dout;
  const int64_t sYc = (int64_t)Hout * Wout * Dout;
  const int64_t sYh = (int64_t)Wout * Dout;
  const int64_t sYw = (int64_t)Dout;
  const int ph0 = threadIdx.y * stride;
  const int pw0 = threadIdx.x * stride;
  const int64_t xsize = (int64_t)patch_h * patch_w * CIN * D;
  for (int64_t idx = tid; idx < xsize; idx += num_threads) {
    int d   = (int)(idx % D);
    int64_t rem = idx / D;
    int c   = (int)(rem % CIN);
    rem     = rem / CIN;
    int pw  = (int)(rem % patch_w);
    int ph  = (int)(rem / patch_w);
    int ih  = in_h_base + ph;
    int iw  = in_w_base + pw;
    T val = T(0);
    if (ih >= 0 && ih < H && iw >= 0 && iw < W) {
      int64_t off = (int64_t)n * sXn + (int64_t)c * sXc +
                    (int64_t)ih * sXh + (int64_t)iw * sXw + d;
      val = X[off];
    }
    sX_ptr[idx] = val;
  }
  __syncthreads();
  constexpr int PATCH_ELEMS = CIN * KH * KW;
  for (int od = 0; od < Dout; ++od) {
    const int id = od * stride - padding;
    const bool id_valid = (id >= 0 && id < D);
    if (valid_out) {
      float xreg[PATCH_ELEMS];
      int ridx = 0;
      #pragma unroll
      for (int ic = 0; ic < CIN; ++ic) {
        #pragma unroll
        for (int kh = 0; kh < KH; ++kh) {
          int ph = ph0 + kh * dilation;
          #pragma unroll
          for (int kw = 0; kw < KW; ++kw) {
            int pw = pw0 + kw * dilation;
            xreg[ridx++] = id_valid ? (float)sX(ph, pw, ic, id) : 0.0f;
          }
        }
      }
      for (int oc = 0; oc < Cout; ++oc) {
        float acc = (Bias != nullptr) ? (float)Bias[oc] : 0.0f;
        int r2 = 0;
        #pragma unroll
        for (int ic = 0; ic < CIN; ++ic) {
          #pragma unroll
          for (int kh = 0; kh < KH; ++kh) {
            #pragma unroll
            for (int kw = 0; kw < KW; ++kw) {
              float wval = (float)sW(oc, ic, kh, kw);
              acc += xreg[r2++] * wval;
            }
          }
        }
        int64_t out_off = (int64_t)n * sYn + (int64_t)oc * sYc +
                           (int64_t)oh * sYh + (int64_t)ow * sYw + od;
        Y[out_off] = (T)acc;
      }
    }
  }
}
// Generic fallback kernel for arbitrary (Cin, Kh, Kw) shapes not covered by
// the statically-specialized kernel above. It recomputes the shared-memory
// resident input values directly inside the Cout loop instead of caching
// them in a dynamically-indexed register array, since the compiler cannot
// map a runtime-bounded array to physical registers (that would otherwise
// silently spill to slow local memory).
template <typename T, int TILE_OH, int TILE_OW>
__global__ void conv_hw_tiled_kernel_generic(
    const T* __restrict__ X,
    const T* __restrict__ Wt,
    const T* __restrict__ Bias,
    T* __restrict__ Y,
    int N, int Cin, int H, int W, int D,
    int Cout, int Kh, int Kw,
    int Hout, int Wout, int Dout,
    int stride, int padding, int dilation,
    int patch_h, int patch_w)
{
  extern __shared__ __align__(16) unsigned char smem_raw[];
  T* sW_ptr = reinterpret_cast<T*>(smem_raw);
  T* sX_ptr = sW_ptr + (size_t)Cout * Cin * Kh * Kw;
  auto sW = make_tensor(make_smem_ptr(sW_ptr),
                         make_shape(Cout, Cin, Kh, Kw),
                         make_stride(Cin * Kh * Kw, Kh * Kw, Kw, 1));
  auto sX = make_tensor(make_smem_ptr(sX_ptr),
                         make_shape(patch_h, patch_w, Cin, D),
                         make_stride(patch_w * Cin * D, Cin * D, D, 1));
  const int tile_idx_w = blockIdx.x;
  const int tile_idx_h = blockIdx.y;
  const int n  = blockIdx.z;
  const int oh_base = tile_idx_h * TILE_OH;
  const int ow_base = tile_idx_w * TILE_OW;
  const int tid = threadIdx.y * blockDim.x + threadIdx.x;
  const int num_threads = blockDim.x * blockDim.y;
  const int wsize = Cout * Cin * Kh * Kw;
  {
    const int wsize4 = wsize / 4;
    const float4* Wt4 = reinterpret_cast<const float4*>(Wt);
    float4* sW4 = reinterpret_cast<float4*>(sW_ptr);
    for (int idx = tid; idx < wsize4; idx += num_threads) {
      sW4[idx] = Wt4[idx];
    }
    for (int idx = wsize4 * 4 + tid; idx < wsize; idx += num_threads) {
      sW_ptr[idx] = Wt[idx];
    }
  }
  const int64_t sXn = (int64_t)Cin * H * W * D;
  const int64_t sXc = (int64_t)H * W * D;
  const int64_t sXh = (int64_t)W * D;
  const int64_t sXw = (int64_t)D;
  const int in_h_base = oh_base * stride - padding;
  const int in_w_base = ow_base * stride - padding;
  const int oh = oh_base + threadIdx.y;
  const int ow = ow_base + threadIdx.x;
  const bool valid_out = (oh < Hout) && (ow < Wout);
  const int64_t sYn = (int64_t)Cout * Hout * Wout * Dout;
  const int64_t sYc = (int64_t)Hout * Wout * Dout;
  const int64_t sYh = (int64_t)Wout * Dout;
  const int64_t sYw = (int64_t)Dout;
  const int ph0 = threadIdx.y * stride;
  const int pw0 = threadIdx.x * stride;
  const int64_t xsize = (int64_t)patch_h * patch_w * Cin * D;
  for (int64_t idx = tid; idx < xsize; idx += num_threads) {
    int d   = (int)(idx % D);
    int64_t rem = idx / D;
    int c   = (int)(rem % Cin);
    rem     = rem / Cin;
    int pw  = (int)(rem % patch_w);
    int ph  = (int)(rem / patch_w);
    int ih  = in_h_base + ph;
    int iw  = in_w_base + pw;
    T val = T(0);
    if (ih >= 0 && ih < H && iw >= 0 && iw < W) {
      int64_t off = (int64_t)n * sXn + (int64_t)c * sXc +
                    (int64_t)ih * sXh + (int64_t)iw * sXw + d;
      val = X[off];
    }
    sX_ptr[idx] = val;
  }
  __syncthreads();
  for (int od = 0; od < Dout; ++od) {
    const int id = od * stride - padding;
    const bool id_valid = (id >= 0 && id < D);
    if (valid_out) {
      for (int oc = 0; oc < Cout; ++oc) {
        float acc = (Bias != nullptr) ? (float)Bias[oc] : 0.0f;
        for (int ic = 0; ic < Cin; ++ic) {
          for (int kh = 0; kh < Kh; ++kh) {
            int ph = ph0 + kh * dilation;
            for (int kw = 0; kw < Kw; ++kw) {
              int pw = pw0 + kw * dilation;
              float xval = id_valid ? (float)sX(ph, pw, ic, id) : 0.0f;
              float wval = (float)sW(oc, ic, kh, kw);
              acc += xval * wval;
            }
          }
        }
        int64_t out_off = (int64_t)n * sYn + (int64_t)oc * sYc +
                           (int64_t)oh * sYh + (int64_t)ow * sYw + od;
        Y[out_off] = (T)acc;
      }
    }
  }
}
torch::Tensor conv_hw_forward(torch::Tensor x,
                               torch::Tensor weight,
                               c10::optional<torch::Tensor> bias,
                               int stride, int padding, int dilation, int groups) {
  TORCH_CHECK(x.is_cuda() && weight.is_cuda(), "tensors must be CUDA");
  TORCH_CHECK(x.scalar_type() == at::kFloat && weight.scalar_type() == at::kFloat,
              "only float32 supported");
  TORCH_CHECK(x.dim() == 5, "x must be [N, C, H, W, D]");
  TORCH_CHECK(weight.dim() == 5, "weight must be [Cout, Cin, Kh, Kw, Kd]");
  TORCH_CHECK(groups == 1, "only groups == 1 supported");
  TORCH_CHECK(weight.size(4) == 1, "depth kernel extent must be 1");
  auto x_c = x.contiguous();
  auto w_c = weight.contiguous();
  int N    = (int)x_c.size(0);
  int Cin  = (int)x_c.size(1);
  int H    = (int)x_c.size(2);
  int W    = (int)x_c.size(3);
  int D    = (int)x_c.size(4);
  int Cout = (int)w_c.size(0);
  int Cin_w= (int)w_c.size(1);
  int Kh   = (int)w_c.size(2);
  int Kw   = (int)w_c.size(3);
  int Kd   = (int)w_c.size(4);
  TORCH_CHECK(Cin_w == Cin, "weight in-channels mismatch");
  TORCH_CHECK(Kd == 1, "depth kernel size must be 1");
  TORCH_CHECK(stride > 0 && dilation > 0, "stride/dilation must be > 0");
  TORCH_CHECK(padding >= 0, "padding must be >= 0");
  int Hout = (H + 2 * padding - dilation * (Kh - 1) - 1) / stride + 1;
  int Wout = (W + 2 * padding - dilation * (Kw - 1) - 1) / stride + 1;
  int Dout = (D + 2 * padding - dilation * (Kd - 1) - 1) / stride + 1;
  TORCH_CHECK(Hout > 0 && Wout > 0 && Dout > 0, "invalid output size computed");
  torch::Tensor b_c;
  const float* b_ptr = nullptr;
  if (bias.has_value()) {
    b_c = bias.value().contiguous();
    TORCH_CHECK(b_c.dim() == 1 && b_c.size(0) == Cout, "bias must be [Cout]");
    b_ptr = b_c.data_ptr<float>();
  }
  auto y = torch::empty({N, Cout, Hout, Wout, Dout}, x.options());
  constexpr int TILE_OH = 16;
  constexpr int TILE_OW = 16;
  int patch_h = (TILE_OH - 1) * stride + (Kh - 1) * dilation + 1;
  int patch_w = (TILE_OW - 1) * stride + (Kw - 1) * dilation + 1;
  size_t smem_bytes = (size_t)(Cout * Cin * Kh * Kw + (size_t)patch_h * patch_w * Cin * D) * sizeof(float);
  dim3 block(TILE_OW, TILE_OH);
  dim3 grid(
      (unsigned)((Wout + TILE_OW - 1) / TILE_OW),
      (unsigned)((Hout + TILE_OH - 1) / TILE_OH),
      (unsigned)(N)
  );
  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  bool launched = false;
  #define LAUNCH_CACHED(CIN_V, KH_V, KW_V)                                          \
    do {                                                                             \
      if (!launched && Cin == (CIN_V) && Kh == (KH_V) && Kw == (KW_V)) {             \
        auto kernel_fn = conv_hw_tiled_kernel_cached<float, TILE_OH, TILE_OW,        \
                                                      (CIN_V), (KH_V), (KW_V)>;      \
        if (smem_bytes > 48 * 1024) {                                                \
          cudaFuncSetAttribute(kernel_fn,                                            \
              cudaFuncAttributeMaxDynamicSharedMemorySize, (int)smem_bytes);          \
        }                                                                            \
        kernel_fn<<<grid, block, smem_bytes, stream>>>(                               \
            x_c.data_ptr<float>(), w_c.data_ptr<float>(), b_ptr,                      \
            y.data_ptr<float>(), N, H, W, D, Cout, Hout, Wout, Dout,                  \
            stride, padding, dilation, patch_h, patch_w);                            \
        launched = true;                                                             \
      }                                                                              \
    } while (0)
  LAUNCH_CACHED(3, 3, 3);
  LAUNCH_CACHED(1, 1, 1);
  LAUNCH_CACHED(3, 5, 5);
  LAUNCH_CACHED(3, 7, 7);
  LAUNCH_CACHED(3, 1, 1);
  #undef LAUNCH_CACHED
  if (!launched) {
    auto kernel_fn = conv_hw_tiled_kernel_generic<float, TILE_OH, TILE_OW>;
    if (smem_bytes > 48 * 1024) {
      cudaFuncSetAttribute(kernel_fn, cudaFuncAttributeMaxDynamicSharedMemorySize, (int)smem_bytes);
    }
    kernel_fn<<<grid, block, smem_bytes, stream>>>(
        x_c.data_ptr<float>(),
        w_c.data_ptr<float>(),
        b_ptr,
        y.data_ptr<float>(),
        N, Cin, H, W, D,
        Cout, Kh, Kw,
        Hout, Wout, Dout,
        stride, padding, dilation,
        patch_h, patch_w
    );
  }
  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "conv_hw_tiled_kernel launch failed: ", cudaGetErrorString(err));
  return y;
}
"""

conv_ext = load_inline(
    name="cute_conv_hw_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["conv_hw_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=["/root/cutegen_test/cutegen/cutlass/include"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    3D convolution with kernel_size = (K, K, 1), implemented with a single
    custom CUDA/CUTE kernel that performs a cooperative tiled 2D convolution
    over the (H, W) spatial dims for every (batch, depth) slice.
    """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int,
                 stride: int = 1, padding: int = 0, dilation: int = 1,
                 groups: int = 1, bias: bool = False):
        super().__init__()
        assert groups == 1, "only groups == 1 supported by this custom kernel"

        self.in_channels = int(in_channels)
        self.out_channels = int(out_channels)
        self.kernel_size = int(kernel_size)
        self.stride = int(stride)
        self.padding = int(padding)
        self.dilation = int(dilation)
        self.groups = int(groups)

        K = self.kernel_size
        Cin = self.in_channels
        Cout = self.out_channels

        # Weight layout matches nn.Conv3d: (Cout, Cin/groups, kD, kH, kW)
        # Here kernel_size passed as (K, K, 1) -> (Cout, Cin, K, K, 1)
        self.weight = nn.Parameter(torch.empty(Cout, Cin, K, K, 1))
        if bias:
            self.bias = nn.Parameter(torch.empty(Cout))
        else:
            self.register_parameter("bias", None)

        self.reset_parameters()
        self._ext = conv_ext

    def reset_parameters(self):
        init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        if self.bias is not None:
            fan_in = self.in_channels * self.kernel_size * self.kernel_size * 1
            bound = 1.0 / math.sqrt(fan_in) if fan_in > 0 else 0.0
            init.uniform_(self.bias, -bound, bound)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.conv_hw_forward(
            x.contiguous(),
            self.weight.contiguous(),
            self.bias if self.bias is not None else None,
            self.stride,
            self.padding,
            self.dilation,
            self.groups,
        )

