  const int oh = oh_base + threadIdx.y;
  const int ow = ow_base + threadIdx.x;
  const bool valid_out = (oh < Hout) && (ow < Wout);

  if (valid_out) {
    const int ph0 = threadIdx.y * stride;
    const int pw0 = threadIdx.x * stride;

    const int64_t sYn = (int64_t)Cout * Hout * Wout * Dout;
    const int64_t sYc = (int64_t)Hout * Wout * Dout;
    const int64_t sYh = (int64_t)Wout * Dout;
